{
    decimal subtotal = 0m;
    foreach (var line in order.Lines)
        subtotal += line.UnitPrice * line.Quantity;

    decimal adjusted = subtotal;
    if (tier == CustomerTier.Wholesale)
        adjusted *= 0.95m;
    else if (tier == CustomerTier.Blocked)
        return 0m;

    if (order.DiscountOverride is { } ovr && ovr > 0m)
        adjusted -= ovr;

    if (subtotal > 500m)
        adjusted -= 10m;

    adjusted = order.Channel switch
    {
        OrderChannel.Web => adjusted,
        OrderChannel.Phone => adjusted + 2m,
        OrderChannel.Marketplace => adjusted * 1.02m,
        _ => adjusted,
    };

    return adjusted < 0m ? 0m : adjusted;
}

